def family_init(ctx):
    ctx.e = ctx.indicator("ema", period=int(ctx.p.ema_n))
    ctx.a = ctx.indicator("atr", period=int(ctx.p.atr_body_n))


def signal(ctx, i):
    if i < 2:
        return 0
    a = ctx.a[i - 1]
    e = ctx.e[i - 1]
    if a is None or e is None or a <= 0:
        return 0
    o1, c1 = ctx.o[i - 1], ctx.c[i - 1]
    o2, c2 = ctx.o[i], ctx.c[i]
    minb = float(ctx.p.min_body_atr) * a
    cap = float(ctx.p.body_ratio)

    # HOMING PIGEON: downtrend, both bars black, body2 strictly inside body1.
    # Goo/Chen/Chang inequality chain: O1 > O2 > C2 > C1.
    if c1 < e:
        b1 = o1 - c1
        b2 = o2 - c2
        if b1 >= minb and b2 > 0.0 and o1 > o2 and c2 > c1 and b2 <= cap * b1:
            return 1

    # DESCENDING HAWK: the exact mirror. C1 > C2 > O2 > O1, both white.
    if c1 > e:
        b1 = c1 - o1
        b2 = c2 - o2
        if b1 >= minb and b2 > 0.0 and c1 > c2 and o2 > o1 and b2 <= cap * b1:
            return -1
    return 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    held = i - min(p["entry_i"] for p in ctx.positions)
    return held >= int(ctx.p.hold)
